/**
 * 年度爱曲取数（/files/yfps/list20xx.json）。
 * 每年一份榜单，曲绘也取那一年的样子（见 illChange.js）。
 */
import { loadJson } from './jsonCache.js'
import { decorateSongMap } from './common.js'
import { loadIllChange } from './illChange.js'

export async function getYfpsList(jsonPath, ymd) {
  try {
    const [jsonData, illChange] = await Promise.all([loadJson(jsonPath), loadIllChange()])
    // 年度爱曲只需要封面，不需要难度配色
    return decorateSongMap(jsonData, [], illChange, ymd)
  } catch (error) {
    console.error('获取数据失败：', error)
    console.error('实际请求的JSON文件路径：', jsonPath)
    return {}
  }
}
