/**
 * 旧曲绘变更日期表（/files/illchange.json，由 python/getIllChange.py 生成）。
 * 年度爱曲、PMT 图池这种按年份组织的老页面靠它显示「当年那张曲绘」。
 */
import { loadJson } from './jsonCache.js'

export function loadIllChange() {
  return loadJson('/files/illchange.json').catch((error) => {
    console.error('获取曲绘变更表失败：', error)
    return {}
  })
}
